import * as React from "react";
import { graphql, Link, type HeadFC } from "gatsby";
import { useI18next, useTranslation } from "gatsby-plugin-react-i18next";
import info from "../data/data.json";
import SEO from "../components/seo";
import Layout from "../components/layout";
import { AuditRequestButton } from "../components/auditRequestModal";
import { trackEvent } from "../utils/analytics";
import {
  livePortfolioImageMap,
  projectRelatedServiceKeys,
  type LivePortfolioProject,
} from "../utils/livePortfolio";
import { getLocaleValue } from "../utils/localeValue";

type PageContext = {
  imageKey: keyof typeof livePortfolioImageMap;
  slug: string;
  language: string;
};

function ArrowIcon() {
  return (
    <svg className="arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true">
      <path d="M5 12h14M13 5l7 7-7 7" />
    </svg>
  );
}

export default function CaseStudyPage({ pageContext }: { pageContext: PageContext }) {
  const { t } = useTranslation();
  const { language } = useI18next();
  const { imageKey } = pageContext;

  const liveProjects = (t("portfolio.live.items", { returnObjects: true }) as LivePortfolioProject[]) || [];
  const project = liveProjects.find((p) => p.imageKey === imageKey);
  const images = livePortfolioImageMap[imageKey];

  const servicesItems = (t("services.items", { returnObjects: true }) as Array<{
    key: string; title: string; href: string;
  }>) || [];

  const relatedServices = (projectRelatedServiceKeys[imageKey] || [])
    .map((serviceKey) => servicesItems.find((item) => item.key === serviceKey))
    .filter((item): item is { key: string; title: string; href: string } => Boolean(item));

  const portfolioPath = language === "fr" ? "/fr/portfolio/" : "/en/portfolio/";

  if (!project || !images) {
    return (
      <Layout data={info}>
        <main>
          <section className="shell" style={{ paddingTop: "80px", paddingBottom: "80px", textAlign: "center" }}>
            <p className="body-lg muted">{t("caseStudy.back")}</p>
            <Link to={portfolioPath} className="btn btn-ghost" style={{ marginTop: "24px", display: "inline-flex" }}>
              ← {t("menu.portfolio")}
            </Link>
          </section>
        </main>
      </Layout>
    );
  }

  const designImage = "design" in images
    ? (images.design as { src: string; alt?: string } | undefined)
    : undefined;

  const sectionCount = { use: 2, highlights: project.highlights.length ? 3 : 0, related: relatedServices.length ? 4 : 0 };
  const ctaNum = relatedServices.length ? 5 : project.highlights.length ? 4 : 3;

  return (
    <Layout data={info}>
      <main>

        {/* ── Breadcrumb */}
        <div style={{ borderBottom: "1px solid var(--rule)", background: "var(--bg-2)" }}>
          <div className="shell" style={{ padding: "12px var(--shell-pad)" }}>
            <nav aria-label="breadcrumb" style={{ display: "flex", alignItems: "center", gap: "8px" }}>
              <Link
                to={portfolioPath}
                className="mono muted"
                style={{ fontSize: "12px", textDecoration: "none", transition: "color 0.2s" }}
              >
                {t("menu.portfolio")}
              </Link>
              <span className="mono muted" style={{ fontSize: "12px" }}>/</span>
              <span className="mono" style={{ fontSize: "12px" }}>{project.title}</span>
            </nav>
          </div>
        </div>

        {/* ── HERO */}
        <section className="pf-hero shell">
          <div className="pf-hero-grid">

            <div className="pf-hero-meta">
              <div className="eyebrow">§ 01 · {t("caseStudy.label") || "Case Study"}</div>
              <img
                src={images.logo.src}
                alt={images.logo.alt || `${project.title} logo`}
                height={40}
                style={{ height: "36px", width: "auto", display: "block", marginTop: "8px", opacity: 0.85 }}
                decoding="async"
              />
            </div>

            <h1
              className="display-xl pf-title reveal"
              aria-label={project.title}
            >
              {project.title}
            </h1>

            <p className="mono muted reveal" style={{ fontSize: "13px", letterSpacing: "0.06em" }}>
              {project.role}
              {project.stack ? <> · <span style={{ opacity: 0.7 }}>{project.stack}</span></> : null}
            </p>

            {project.note ? (
              <p className="body-lg pf-intro reveal">{project.note}</p>
            ) : null}

            <div className="reveal" style={{ display: "flex", gap: "12px", flexWrap: "wrap", paddingTop: "8px" }}>
              <a
                href={project.href}
                target="_blank"
                rel="noreferrer"
                className="btn btn-dark"
                onClick={() => trackEvent("portfolio_click", { source: "case-study.hero", project_name: project.title, target_url: project.href })}
              >
                {t("caseStudy.visitSite")}
                <ArrowIcon />
              </a>
              <Link to={portfolioPath} className="btn btn-ghost">
                ← {t("caseStudy.back")}
              </Link>
            </div>

          </div>
        </section>

        {/* ── Hero image */}
        <div style={{ borderTop: "1px solid var(--rule)", borderBottom: "1px solid var(--rule)", overflow: "hidden", maxHeight: "600px" }}>
          <img
            src={images.large.src}
            alt={images.large.alt || project.title}
            decoding="async"
            width={1600}
            height={900}
            style={{ width: "100%", objectFit: "cover", objectPosition: "top", display: "block" }}
          />
        </div>

        {/* ── USE CASE */}
        {project.useCase ? (
          <section className="who shell">
            <header className="sec-head">
              <div className="eyebrow">§ 02 · {t("selectedProjects.labels.useCase")}</div>
              <h2 className="display-l reveal">{t("selectedProjects.labels.useCase")}</h2>
              <p className="body-lg reveal">{project.useCase.summary}</p>
            </header>

            {/* Figma design image */}
            {designImage ? (
              <div className="reveal" style={{ marginBottom: "32px", border: "1px solid var(--rule)", borderRadius: "16px", overflow: "hidden" }}>
                <div style={{ padding: "10px 20px", borderBottom: "1px solid var(--rule)", background: "var(--bg-2)", display: "flex", gap: "8px", alignItems: "center" }}>
                  <span className="eyebrow" style={{ fontSize: "10px" }}>{t("caseStudy.design")}</span>
                  <span className="mono muted" style={{ fontSize: "10px" }}>· Figma</span>
                </div>
                <img
                  src={designImage.src}
                  alt={designImage.alt || `${project.title} — Figma design`}
                  style={{ width: "100%", display: "block" }}
                  decoding="async"
                />
              </div>
            ) : null}

            {/* Challenge / Approach / Outcome */}
            <div className="who-grid" style={{ gridTemplateColumns: "repeat(3, 1fr)" }}>
              <article className="who-card tilt reveal">
                <div className="tilt-inner">
                  <h3 className="display-s" style={{ fontSize: "clamp(16px, 1.4vw, 20px)", marginBottom: "16px" }}>
                    {t("selectedProjects.labels.challenge")}
                  </h3>
                  <p className="body" style={{ fontSize: "14px" }}>{project.useCase.challenge}</p>
                </div>
              </article>
              <article className="who-card tilt reveal">
                <div className="tilt-inner">
                  <h3 className="display-s" style={{ fontSize: "clamp(16px, 1.4vw, 20px)", marginBottom: "16px" }}>
                    {t("selectedProjects.labels.approach")}
                  </h3>
                  <p className="body" style={{ fontSize: "14px" }}>{project.useCase.approach}</p>
                </div>
              </article>
              <article className="who-card tilt reveal">
                <div className="tilt-inner">
                  <h3 className="display-s" style={{ fontSize: "clamp(16px, 1.4vw, 20px)", marginBottom: "16px" }}>
                    {t("selectedProjects.labels.outcome")}
                  </h3>
                  <p className="body" style={{ fontSize: "14px" }}>{project.useCase.outcome}</p>
                </div>
              </article>
            </div>
          </section>
        ) : null}

        {/* ── HIGHLIGHTS */}
        {project.highlights.length ? (
          <section className="services shell">
            <header className="sec-head">
              <div className="eyebrow">§ {sectionCount.use + 1} · {t("caseStudy.highlights")}</div>
              <h2 className="display-l reveal">{t("caseStudy.highlights")}</h2>
            </header>
            <ol className="svc-list" data-stagger>
              {project.highlights.map((highlight, i) => (
                <li key={highlight} className="svc reveal">
                  <span className="num">{String(i + 1).padStart(2, "0")}</span>
                  <p className="body" style={{ gridColumn: "2 / -1" }}>{highlight}</p>
                </li>
              ))}
            </ol>
          </section>
        ) : null}

        {/* ── RELATED SERVICES */}
        {relatedServices.length ? (
          <section className="shell" style={{ paddingBottom: "40px" }}>
            <header className="sec-head" style={{ marginBottom: "24px" }}>
              <div className="eyebrow">§ {sectionCount.highlights || sectionCount.use + 1} · {t("caseStudy.relatedServices")}</div>
              <h2 className="display-l reveal">{t("caseStudy.relatedServices")}</h2>
            </header>
            <div className="tag-row">
              {relatedServices.map((service) => (
                <Link
                  key={service.key}
                  to={service.href}
                  className="tag mono"
                  onClick={() => trackEvent("service_related_link_click", {
                    source: "case-study.relatedServices",
                    project_name: project.title,
                    service_key: service.key,
                  })}
                >
                  {service.title}
                </Link>
              ))}
            </div>
          </section>
        ) : null}

        {/* ── CTA */}
        <section className="portfolio-preview shell">
          <div
            className="portfolio-foot"
            style={{ paddingTop: "80px", borderTop: "1px solid var(--rule)" }}
          >
            <div>
              <p className="eyebrow">§ {ctaNum} · {t("selectedProjects.cta.title").split(" ").slice(0, 4).join(" ")}</p>
              <p className="body-lg" style={{ marginTop: "12px", maxWidth: "48ch" }}>
                {t("selectedProjects.cta.desc")}
              </p>
            </div>
            <div style={{ display: "flex", gap: "12px", flexWrap: "wrap", alignSelf: "flex-start" }}>
              <a
                href={project.href}
                target="_blank"
                rel="noreferrer"
                className="btn btn-dark"
                onClick={() => trackEvent("portfolio_click", {
                  source: "case-study.cta",
                  project_name: project.title,
                  target_url: project.href,
                })}
              >
                {t("caseStudy.visitSite")}
                <ArrowIcon />
              </a>
              <AuditRequestButton
                serviceName={t("contact.auditService") as string}
                source="case-study.cta"
                className="btn btn-ghost"
              >
                {t("selectedProjects.labels.requestAudit")}
              </AuditRequestButton>
              <Link to={portfolioPath} className="btn btn-ghost">
                ← {t("caseStudy.back")}
              </Link>
            </div>
          </div>
        </section>

      </main>
    </Layout>
  );
}

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

export const Head: HeadFC<object, PageContext> = ({ location, pageContext }) => {
  const { language, imageKey, slug } = pageContext;
  const items = getLocaleValue<LivePortfolioProject[]>(language, "portfolio.live.items") || [];
  const project = items.find((p) => p.imageKey === imageKey);
  const title = project
    ? `${project.title} — Case Study | Juan Pablo Riano`
    : "Case Study | Juan Pablo Riano";
  const description = project?.useCase?.summary || project?.note || "";
  const pathname = `/${language}/portfolio/case-studies/${slug}/`;
  return (
    <SEO
      data={info}
      title={title}
      description={description}
      pathname={pathname}
      currentPathname={location.pathname}
      language={language}
      alternates={[
        { hrefLang: "fr", href: `https://riano.ca/fr/portfolio/case-studies/${slug}/` },
        { hrefLang: "en", href: `https://riano.ca/en/portfolio/case-studies/${slug}/` },
        { hrefLang: "x-default", href: `https://riano.ca/fr/portfolio/case-studies/${slug}/` },
      ]}
      schemaType="ProfessionalService"
    />
  );
};
